export const BODY: string = "\n<p>WebP هي الصيغة التي أنشأتها غوغل لجعل الويب أسرع، وهي تعمل. صورة JPG قد تصغر بنسبة 30 بالمئة عند تحويلها إلى WebP.</p>\n<p>هذا التوفير مهم. الصور الأصغر تعني صفحات أسرع وزوارًا أكثر سعادة وترتيبًا أفضل في محركات البحث.</p>\n<p>يشرح هذا الدليل كيف يعمل تحويل JPG إلى WebP، وما الإعدادات التي تستخدمها، ومتى تحتفظ بـJPG.</p>\n<h2 id=\"what-is-webp\">ما WebP؟</h2>\n<p>ما WebP؟ صيغة صور حديثة من غوغل، أصغر من JPG بالجودة نفسها. تدعم الضغط مع فقدان ودون فقدان، والشفافية أيضًا.</p>\n<p>WebP تجمع بين مزايا JPG وPNG: صغيرة مثل JPG، وتدعم الشفافية مثل PNG. إنها صيغة الويب الحديثة.</p>\n<h2 id=\"how-much-smaller\">كم يصغّر WebP عن JPG؟</h2>\n<p>كم يصغّر WebP عن JPG؟ بنسبة 25 إلى 35 بالمئة تقريبًا بالجودة نفسها. صورة JPG بحجم 300 كيلوبايت قد تصبح WebP بحجم 200 كيلوبايت.</p>\n<p>التوفير يتراكم عبر موقع كامل. موقع فيه 100 صورة قد يوفر ميغابايتات كاملة، وهذا يختصر وقت التحميل بشكل ملحوظ.</p>\n<h2 id=\"how-conversion-works\">كيف يعمل تحويل JPG إلى WebP؟</h2>\n<p>كيف يعمل تحويل JPG إلى WebP؟ الأداة تفك ضغط JPG إلى بكسلات، ثم تعيد ترميزها كـWebP بضغط أكثر كفاءة. الصورة نفسها لا تتغير تقريبًا.</p>\n<p>التحويل يضيف فقدانًا بسيطًا لأن JPG مضغوط أصلًا. لكن الفقدان ضئيل عند جودة 85 أو أعلى.</p>\n<h2 id=\"quality-settings\">إعدادات الجودة التي تعمل</h2>\n<p>إعدادات الجودة التي تعمل: جودة 85 مناسبة لمعظم صور المواقع، و90 لصور المنتجات المهمة. جودة 80 كافية للصور المصغرة.</p>\n<p>لا تستخدم جودة أقل من 75 للصور الرئيسية. الجودة المنخفضة تظهر تشوهات واضحة في الصور الكبيرة.</p>\n<h2 id=\"browser-support\">ما المتصفحات التي تدعم WebP؟</h2>\n<p>ما المتصفحات التي تدعم WebP؟ كل المتصفحات الحديثة: كروم وفايرفوكس وسفاري وإيدج. الدعم شبه عالمي الآن.</p>\n<p>المتصفحات القديمة جدًا لا تدعم WebP. إذا كان جمهورك يستخدم أجهزة قديمة، فقدم JPG كبديل.</p>\n<h2 id=\"dimensions-preserved\">الأبعاد والبيانات الوصفية</h2>\n<p>الأبعاد والبيانات الوصفية: التحويل يحافظ على أبعاد الصورة. بيانات EXIF قد تُزال، وهذا يحمي خصوصيتك عند النشر.</p>\n<p>إذا أردت الاحتفاظ ببيانات معينة، فتحقق من الملف المحوّل. بعض الأدوات تحافظ على البيانات، وبعضها يزيلها.</p>\n<h2 id=\"wordpress-shopify-wix\">كيف تستخدم WebP في ووردبريس وشوبيفاي وويكس؟</h2>\n<p>كيف تستخدم WebP في ووردبريس وشوبيفاي وويكس؟ ووردبريس يدعم WebP منذ الإصدار 5.8، وشوبيفاي وويكس يدعمانه أيضًا.</p>\n<p>ارفع صور WebP مباشرة إلى منصتك. معظم المنصات الحديثة تقبل WebP دون إضافات.</p>\n<h2 id=\"product-photos\">WebP لصور المنتجات</h2>\n<p>WebP لصور المنتجات: استخدم جودة 90 لصور المنتجات. المنتجات تحتاج إلى أقصى جودة، والعملاء يكبّرون الصور لفحص التفاصيل.</p>\n<p>صور المنتجات كـWebP أصغر وأسرع في التحميل. السرعة تحسّن تجربة التسوق وتزيد المبيعات.</p>\n<h2 id=\"screenshots-with-text\">اللقطات مع النص</h2>\n<p>اللقطات مع النص: استخدم جودة 90 للقطات النصية. النص يحتاج إلى حدة عالية، والجودة المنخفضة تضببه.</p>\n<p>إذا ضبب النص بعد التحويل، فأعد التحويل بجودة أعلى. لا تحوّل من النسخة المحوّلة، بل من JPG الأصلي.</p>\n<h2 id=\"when-webp-is-larger\">متى يكون WebP أكبر؟</h2>\n<p>متى يكون WebP أكبر؟ عندما تكون الصورة بسيطة بألوان قليلة، مثل أيقونة أو رسم بسيط. JPG يضغطها جيدًا أصلًا.</p>\n<p>في هذه الحالة النادرة، احتفظ بـJPG. قارن الحجمين قبل الاعتماد على WebP لكل صورة.</p>\n<h2 id=\"when-to-keep-jpg\">متى تحتفظ بـJPG؟</h2>\n<p>متى تحتفظ بـJPG؟ عندما ترسل الصورة إلى نظام قديم، أو تطبعها، أو ترفعها إلى بوابة لا تدعم WebP. التوافق أهم من الحجم في هذه الحالات.</p>\n<p>احتفظ بنسخة JPG للأرشيف أيضًا. الأصل JPG هو مصدر كل نسخة مستقبلية.</p>\n<h2 id=\"checking-quality\">كيف تراجع الجودة قبل التنزيل؟</h2>\n<p>كيف تراجع الجودة قبل التنزيل؟ قارن النتيجة بالأصل، وتأكد من أن الألوان صحيحة والنص حاد ولا توجد تشوهات.</p>\n<p>كبّر الصورة وافحص التفاصيل الدقيقة. إذا بدت النتيجة جيدة مكبّرة، فهي جاهزة للاستخدام.</p>\n<h2 id=\"webp-for-blogs\">WebP للمدونات</h2>\n<p>WebP للمدونات: حوّل صور مدونتك إلى WebP لتسريع صفحاتك. المدونات السريعة تحتفظ بالقراء وتحسّن ترتيبها في البحث.</p>\n<p>ابدأ بالصور الأكبر أولًا. الصور الكبيرة هي التي تبطئ صفحاتك أكثر من غيرها.</p>\n<h2 id=\"webp-for-shops\">WebP للمتاجر الإلكترونية</h2>\n<p>WebP للمتاجر الإلكترونية: حوّل صور منتجاتك إلى WebP لتسريع صفحات المنتجات. السرعة تحسّن تجربة التسوق وتزيد المبيعات.</p>\n<p>كل ثانية توفرها من وقت التحميل تزيد احتمال الشراء. WebP استثمار صغير بعائد كبير للمتاجر.</p>\n<h2 id=\"webp-for-portfolios\">WebP للمحافظ</h2>\n<p>WebP للمحافظ: حوّل صور محفظتك إلى WebP لعرض أعمالك بسرعة. المحفظة السريعة تترك انطباعًا احترافيًا لدى العملاء.</p>\n<p>العملاء يتصفحون محافظ كثيرة. السرعة تجعل محفظتك مميزة عن غيرها.</p>\n<h2 id=\"webp-for-news\">WebP لمواقع الأخبار</h2>\n<p>WebP لمواقع الأخبار: حوّل صور الأخبار إلى WebP لتسريع صفحاتك. الأخبار تعتمد على السرعة، والقراء لا ينتظرون.</p>\n<p>الصور الأصغر تعني صفحات أسرع، والصفحات الأسرع تعني قراءً أكثر.</p>\n<h2 id=\"measuring-speed-improvement\">كيف تقيس تحسن السرعة؟</h2>\n<p>كيف تقيس تحسن السرعة؟ قارن وقت تحميل الصفحة قبل التحويل وبعده. استخدم أدوات قياس السرعة لمعرفة الفرق الحقيقي.</p>\n<p>إذا تحسّن وقت التحميل بشكل ملحوظ، فالتحويل نجح. إذا لم يتحسن، فابحث عن عناصر أخرى تبطئ صفحتك.</p>\n<h2 id=\"webp-for-documentation-sites\">WebP لمواقع التوثيق</h2>\n<p>WebP لمواقع التوثيق: حوّل صور التوثيق إلى WebP لتسريع صفحاتك. مواقع التوثيق فيها صور كثيرة، والتوفير يتراكم.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-jpg-ila-webp/\">كيفية تحويل JPG إلى WebP</a> و<a href=\"/ar/blog/jpg-vs-webp/\">JPG مقابل WebP</a>، أو حوّل من PNG باستخدام <a href=\"/ar/tahwil-png-ila-webp/\">محول PNG إلى WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يصغّر WebP عن JPG للصورة نفسها؟","answer":"WebP أصغر من JPG بنسبة 25 إلى 35 بالمئة تقريبًا بالجودة نفسها. صورة JPG بحجم 300 كيلوبايت قد تصبح WebP بحجم 200 كيلوبايت."},{"question":"هل تحويل JPG إلى WebP يغيّر أبعاد صورتي؟","answer":"لا، التحويل لا يغيّر أبعاد صورتك. العرض والارتفاع يبقيان كما هما، ويتغير فقط ترميز البيانات."},{"question":"هل يمكنني استخدام صور WebP في ووردبريس؟","answer":"نعم، ووردبريس يدعم WebP منذ الإصدار 5.8. يمكنك رفع صور WebP مباشرة واستخدامها في مقالاتك وصفحاتك."},{"question":"ما إعداد الجودة الذي أستخدمه لصور المواقع؟","answer":"جودة 85 مناسبة لمعظم صور المواقع، و90 لصور المنتجات المهمة. جودة 85 توازن بين الحجم والجودة بشكل ممتاز."},{"question":"هل يعمل تحويل JPG إلى WebP على الهاتف؟","answer":"نعم، يعمل التحويل في متصفح هاتفك دون تثبيت أي تطبيق. افتح الأداة وارفع الصورة وحوّلها ونزّل النتيجة."},{"question":"لماذا أصبح ملف WebP المحوّل أكبر من JPG الأصلي؟","answer":"لأن الصورة بسيطة بألوان قليلة، مثل أيقونة أو رسم بسيط. JPG يضغطها جيدًا أصلًا، وWebP قد يكون أكبر في هذه الحالة النادرة."}];
